def minimumSwap(s1, s2):
    if len(s1) != len(s2):
        return -1

    x_diff = y_diff = 0

    for a, b in zip(s1, s2):
        if a == 'x' and b == 'y':
            x_diff += 1
        elif a == 'y' and b == 'x':
            y_diff += 1

    if (x_diff + y_diff) % 2 != 0:
        return -1

    return x_diff // 2 + y_diff // 2 + x_diff % 2 + y_diff % 2
